<script>import {onMount} from 'svelte';import List from './List.svelte';import Detail from './Detail.svelte';import Form from './Form.svelte';import {grouped} from './store.js';let workflows=[],selectedWorkflow=null,selectedExecution=null,showForm=false,error='';onMount(async()=>{try{workflows=await grouped()}catch(e){error=e.message}});function selectWorkflow(workflow){selectedWorkflow=workflow;selectedExecution=null;showForm=false}function refresh(){grouped().then(value=>workflows=value).catch(e=>error=e.message)}</script>
<div class="browser"><aside><div class="toolbar"><button on:click={()=>showForm=true}>Launch workflow</button><button on:click={refresh}>Refresh</button></div><List {workflows} on:select={e=>selectWorkflow(e.detail)}/></aside><section>{#if error}<p class="error">{error}</p>{/if}{#if showForm}<Form on:started={e=>{selectedExecution=e.detail;showForm=false;refresh()}}/>{:else if selectedExecution}<Detail execution={selectedExecution}/>{:else if selectedWorkflow}<div class="workflow"><h2>{selectedWorkflow.name}</h2><p>{selectedWorkflow.description || 'No description.'}</p><p>Version {selectedWorkflow.version || '1'} · {selectedWorkflow.executions?.length || 0} executions</p><h3>Executions</h3>{#if selectedWorkflow.executions?.length}<ul class="executions">{#each selectedWorkflow.executions as item (item.id)}<li><button on:click={()=>selectedExecution=item}><strong>{item.id}</strong><span>{item._state || item.state || 'Unknown'}</span></button></li>{/each}</ul>{:else}<p>No executions for this workflow.</p>{/if}</div>{:else}<p>Select a workflow.</p>{/if}</section></div><style>.browser{display:grid;grid-template-columns:320px minmax(0,1fr);gap:18px;min-height:calc(100vh - 150px)}aside,section{background:#fff;border:1px solid #d7dce3;border-radius:8px;padding:18px;min-width:0}.toolbar{display:flex;gap:6px;margin-bottom:12px}button{padding:8px 10px;border:1px solid #cbd5e1;background:#fff;border-radius:5px;cursor:pointer}.executions{list-style:none;padding:0}.executions li+li{margin-top:8px}.executions button{display:flex;justify-content:space-between;width:100%;text-align:left}.executions span{color:#697586}.error{color:#b42318}@media(max-width:800px){.browser{grid-template-columns:1fr}}</style>
